"""Play Space Invaders inside the world model: every frame is generated by the network (ROADMAP CP6-B).

    python scripts/play_model.py --ckpt runs/<run>/checkpoints/ckpt_last.pt
    python scripts/play_model.py --ckpt runs/<run>/checkpoints/ckpt_last.pt --side-by-side --hz 8

Keys: A/D or arrows move, Space fires, R resets the scenario, 1-9 pick a scenario, +/- change the
sampling steps, Esc quits. With --side-by-side the real emulator replays the same scenario and
receives the same keys, on the right.
"""

import argparse
import json
import sys
from collections import deque
from pathlib import Path

import numpy as np
import pygame
import torch

sys.path.insert(0, str(Path(__file__).resolve().parent))  # for make_scenarios, also when imported by path

from make_scenarios import Scenario, load_scenario, validate_entries  # noqa: E402
from wm.config import load_config  # noqa: E402
from wm.controls import FireLatch, keys_to_action  # noqa: E402
from wm.data.dataset import LUMA  # noqa: E402
from wm.env import make_env, to_model_frame  # noqa: E402
from wm.eval.baselines import CopyLastFrame  # noqa: E402
from wm.inference import WorldModel, WorldModelProtocol  # noqa: E402

LEFT_KEYS = (pygame.K_a, pygame.K_LEFT)
RIGHT_KEYS = (pygame.K_d, pygame.K_RIGHT)
PLUS_KEYS = (pygame.K_PLUS, pygame.K_EQUALS, pygame.K_KP_PLUS)
MINUS_KEYS = (pygame.K_MINUS, pygame.K_KP_MINUS)
DIGIT_KEYS = {getattr(pygame, f"K_{i}"): i - 1 for i in range(1, 10)}
BAR = 40  # px of text under the frames
CAPTION = "every frame generated by a neural network"


def to_model_input(frames: np.ndarray, C: int) -> torch.Tensor:
    """uint8 (..., H, W, 3) -> float (..., C, H, W) in [-1,1], normalized as WindowDataset does (4.5)."""
    x = torch.from_numpy(frames).movedim(-1, -3).float()  # float before any arithmetic on uint8
    if C == 1:
        x = (x * LUMA[:, None, None]).sum(-3, keepdim=True)
    return x / 127.5 - 1


def to_uint8(x: torch.Tensor) -> np.ndarray:
    """float (..., C, H, W) in [-1,1] -> uint8 (..., H, W, 3); greyscale is repeated to 3 channels."""
    u = ((x.detach().float().cpu().clamp(-1, 1) + 1) * 127.5).round().to(torch.uint8).movedim(-3, -1).numpy()
    return np.repeat(u, 3, axis=-1) if u.shape[-1] == 1 else u


class DemoSession:
    """The model's side of the game: a rolling context of K frames and the actions taken at them."""

    def __init__(self, model: WorldModelProtocol, scenarios: list[Scenario], num_steps: int, max_steps: int,
                 ctx_level: int = 0, cfg_scale: float | None = None, seed: int = 0,
                 device: torch.device | str = "cpu") -> None:
        self.model, self.scenarios = model, scenarios
        self.num_steps, self.max_steps = num_steps, max_steps
        self.ctx_level, self.cfg_scale, self.device = ctx_level, cfg_scale, device
        self.generator = torch.Generator().manual_seed(seed)  # CPU, so a seed gives the same game on any device (D21)
        self.index = 0

    def reset(self, index: int | None = None) -> None:
        """Start (or restart, with None) a scenario from its stored frames and actions."""
        self.index = self.index if index is None else index
        s = self.scenarios[self.index]
        self.context = deque(to_model_input(s.frames, self.model.C), maxlen=self.model.K)
        self.actions = deque(s.actions.tolist(), maxlen=self.model.K - 1)
        self.frame = s.frames[-1]

    def step(self, action: int) -> np.ndarray:
        """Generate the frame that `action`, taken at the current frame, leads to (4.4 alignment)."""
        context = torch.stack(list(self.context))[None].to(self.device)
        actions = torch.tensor([list(self.actions) + [action]], dtype=torch.long, device=self.device)
        out = self.model.predict_next(context, actions, num_steps=self.num_steps, cfg_scale=self.cfg_scale,
                                      ctx_level=self.ctx_level, generator=self.generator)[0].cpu().clamp(-1, 1)
        self.context.append(out)
        self.actions.append(action)
        self.frame = to_uint8(out)
        return self.frame

    def change_steps(self, delta: int) -> int:
        """Change the number of sampler steps, kept in 1..max_steps."""
        self.num_steps = min(max(self.num_steps + delta, 1), self.max_steps)
        return self.num_steps


class RealReplay:
    """The real emulator, replayed to a scenario's row (D9), then driven by the player's actions."""

    def __init__(self, scenario: Scenario) -> None:
        self.scenario = scenario
        self.env = make_env(scenario.seed)
        obs, info = self.env.reset()
        if info["noops"] != scenario.noops:
            raise RuntimeError(f"replay of {scenario.name}: {info['noops']} no-ops, stored {scenario.noops}")
        for a in scenario.prefix_actions:
            obs, *_ = self.env.step(int(a))
        self.frame = self._model_frame(obs)
        if not np.array_equal(self.frame, scenario.frames[-1]):
            raise RuntimeError(f"replay of {scenario.name} does not reach its stored frame")
        self.done = False

    def _model_frame(self, obs: np.ndarray) -> np.ndarray:
        return to_model_frame(obs, self.scenario.resolution, self.scenario.resize_method)

    def step(self, action: int) -> tuple[np.ndarray, bool]:
        """Step with `action` unless the game is over; returns the frame and whether it is over."""
        if not self.done:
            obs, _, terminated, truncated, _ = self.env.step(action)
            self.frame, self.done = self._model_frame(obs), terminated or truncated
        return self.frame, self.done

    def close(self) -> None:
        self.env.close()


def display_array(frame: np.ndarray, scale: int, widen: int) -> np.ndarray:
    """Upscale an (H,W,3) frame for display only (×widen horizontally) and transpose to pygame's (W,H,3)."""
    return frame.repeat(scale, axis=0).repeat(scale * widen, axis=1).swapaxes(0, 1)


def pick_device(name: str | None) -> torch.device:
    """The configured device, or cuda, then mps (Mac laptops, for the demo), then cpu."""
    if name:
        return torch.device(name)
    if torch.cuda.is_available():
        return torch.device("cuda")
    return torch.device("mps" if torch.backends.mps.is_available() else "cpu")


def run(cfg: dict, model: WorldModelProtocol, scenarios: list[Scenario], side_by_side: bool = False,
        device: torch.device | str = "cpu", max_ticks: int | None = None) -> int:
    """Run the game loop until Esc, window close, or `max_ticks`; return the number of ticks run."""
    default_steps = getattr(getattr(model, "sampler", None), "num_steps", 2)
    session = DemoSession(model, scenarios, cfg["num_steps"] or default_steps, int(cfg["max_steps"]),
                          int(cfg["ctx_level"]), cfg["cfg_scale"], int(cfg["seed"]), device)
    session.reset(int(cfg["scenario"]))
    real = RealReplay(scenarios[session.index]) if side_by_side else None

    pygame.init()
    scale, widen = int(cfg["scale"]), int(cfg["widen"])
    panel_w, panel_h = model.W * scale * widen, model.H * scale
    screen = pygame.display.set_mode((panel_w * (2 if real else 1), panel_h + BAR))
    font = pygame.font.Font(None, 18)
    clock, latch = pygame.time.Clock(), FireLatch()

    def restart(index: int | None = None) -> None:
        nonlocal real
        session.reset(index)
        if real:
            real.close()
            real = RealReplay(scenarios[session.index])

    ticks, running = 0, True
    while running and (max_ticks is None or ticks < max_ticks):
        for event in pygame.event.get():
            if event.type == pygame.QUIT or (event.type == pygame.KEYDOWN and event.key == pygame.K_ESCAPE):
                running = False
            elif event.type != pygame.KEYDOWN:
                continue
            elif event.key == pygame.K_SPACE:
                latch.press()
            elif event.key == pygame.K_r:
                restart()
            elif event.key in DIGIT_KEYS and DIGIT_KEYS[event.key] < len(scenarios):
                restart(DIGIT_KEYS[event.key])
            elif event.key in PLUS_KEYS:
                session.change_steps(1)
            elif event.key in MINUS_KEYS:
                session.change_steps(-1)

        keys = pygame.key.get_pressed()
        fire = latch.tick(keys[pygame.K_SPACE])
        action = keys_to_action(any(keys[k] for k in LEFT_KEYS), any(keys[k] for k in RIGHT_KEYS), fire)
        session.step(action)
        screen.fill((0, 0, 0))
        screen.blit(pygame.surfarray.make_surface(display_array(session.frame, scale, widen)), (0, 0))
        if real:
            frame, done = real.step(action)
            screen.blit(pygame.surfarray.make_surface(display_array(frame, scale, widen)), (panel_w, 0))
            label = "real game: GAME OVER (R resets)" if done else "real game"
            screen.blit(font.render(label, True, (255, 255, 255)), (panel_w + 6, panel_h + 4))
        name = scenarios[session.index].name
        status = f"{clock.get_fps():4.1f} fps | {session.num_steps} steps | {session.index + 1}: {name}"
        screen.blit(font.render(CAPTION, True, (255, 255, 255)), (6, panel_h + 4))
        screen.blit(font.render(status, True, (170, 170, 170)), (6, panel_h + 22))
        pygame.display.set_caption(f"Space Invaders world model | {name}")
        pygame.display.flip()
        clock.tick(float(cfg["hz"]))
        ticks += 1

    if real:
        real.close()
    pygame.quit()
    return ticks


def load_model(spec: str, K: int, device: torch.device) -> WorldModelProtocol:
    """A checkpoint path, or copy_last for trying the demo without a model."""
    if spec == "copy_last":
        return CopyLastFrame(K, 3, 84, 84)
    return WorldModel.from_checkpoint(spec, device=device)


def main(argv: list[str] | None = None) -> None:
    p = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    p.add_argument("--config", default="configs/demo/play.yaml")
    p.add_argument("--set", nargs="*", default=[], metavar="KEY=VALUE")
    p.add_argument("--ckpt", help="checkpoint path, or copy_last")
    p.add_argument("--hz", type=float, help="target ticks per second")
    p.add_argument("--side-by-side", action="store_true", help="run the real emulator next to the model")
    args = p.parse_args(argv)
    cfg = load_config(args.config, args.set)
    cfg["ckpt"] = args.ckpt or cfg["ckpt"]
    cfg["hz"] = args.hz if args.hz is not None else cfg["hz"]
    if not cfg["ckpt"]:
        p.error("give a checkpoint with --ckpt (or --ckpt copy_last)")
    device = pick_device(cfg["device"])
    model = load_model(cfg["ckpt"], int(cfg["K"]), device)
    entries = json.loads(Path(cfg["scenarios"]).read_text())
    validate_entries(entries)
    scenarios = [load_scenario(e, model.K) for e in entries]
    print(f"{cfg['ckpt']} on {device}; scenarios: " + ", ".join(f"{i + 1} {s.name}" for i, s in enumerate(scenarios)))
    run(cfg, model, scenarios, side_by_side=args.side_by_side or bool(cfg["side_by_side"]), device=device)


if __name__ == "__main__":
    main()
